commands.command:
set -eu
cd /srv/legacy2/child-process-reaping
backup=/var/tmp/supervisor.py.pre-reaping-fix
cp --preserve=mode,ownership,timestamps supervisor.py "$backup"
chmod 600 "$backup"
cat > /tmp/supervisor.py.candidate <<'PY'
#!/usr/bin/python
import os
import sys
import time


def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: supervisor.py JOB_COUNT")

    try:
        job_count = int(sys.argv[1])
    except ValueError:
        raise SystemExit("JOB_COUNT must be an integer")
    if job_count < 0:
        raise SystemExit("JOB_COUNT must be non-negative")

    base = os.path.dirname(os.path.abspath(__file__))
    children = {}

    for number in range(job_count):
        pid = os.fork()
        if pid == 0:
            time.sleep(0.1)
            os._exit((number % 2) * 3)
        children[pid] = number

    statuses = {}
    while children:
        try:
            pid, wait_status = os.wait()
        except InterruptedError:
            continue
        number = children.pop(pid, None)
        if number is not None:
            statuses[number] = os.waitstatus_to_exitcode(wait_status)

    results_path = os.path.join(base, "results.tsv")
    run_id = str(os.getpid())
    with open(results_path, "a", encoding="utf-8") as results:
        for number in range(job_count):
            results.write(f"{run_id},{number},{statuses[number]}\n")
        results.flush()
        os.fsync(results.fileno())


if __name__ == "__main__":
    main()
PY
python3 -c 'compile(open("/tmp/supervisor.py.candidate", encoding="utf-8").read(), "supervisor.py", "exec")'
install -o root -g root -m 0755 /tmp/supervisor.py.candidate supervisor.py
rm -f /tmp/supervisor.py.candidate
printf 'installed metadata:\n'; stat -c '%A %a %U:%G %s %y %n' supervisor.py
printf 'installed checksum:\n'; sha256sum supervisor.py
printf 'installed source:\n'; nl -ba supervisor.py
printf 'rollback_copy:\n'; stat -c '%A %a %U:%G %s %n' "$backup"
